"""Tests of navera_lite/geo.py (mission 06). Written for the course; it is not NAVERA code.

Run from the lesson folder:  python3 -m pytest navera_lite/tests/test_geo.py -q
"""
import math

import numpy as np
import pytest

from navera_lite import geo


def test_null_island_and_bad_values_are_refused():
    assert geo.is_finite_latlon(-1.2921, 36.8219)
    assert not geo.is_finite_latlon(0.0, 0.0)
    assert not geo.is_finite_latlon(float("nan"), 10.0)
    assert not geo.is_finite_latlon(91.0, 10.0)
    assert not geo.is_finite_latlon(None, 10.0)


def test_enu_flat_and_offset_are_inverse():
    for lat, lon, e, n in [(60.17, 24.94, 1500.0, -800.0), (-22.9, -43.2, -300.0, 2500.0)]:
        lat2, lon2 = geo.offset(lat, lon, e, n)
        back = geo.enu_flat(lat, lon, lat2, lon2)
        assert back == pytest.approx((e, n), abs=1e-6)


def test_enu_flat_crosses_the_date_line():
    e, n = geo.enu_flat(-17.0, 179.95, -17.0, -179.95)
    assert 10_000 < e < 11_000 and abs(n) < 1e-6


def test_haversine_known_values_and_arrays():
    assert geo.haversine_m(10.0, 20.0, 10.0, 20.0) == 0.0
    one_degree = math.pi * geo.EARTH_RADIUS_M / 180.0
    assert geo.haversine_m(0.0, 0.0, 1.0, 0.0) == pytest.approx(one_degree, rel=1e-12)
    d = geo.haversine_m(np.zeros(3), np.zeros(3), np.array([0.0, 0.0, 90.0]), np.array([90.0, 180.0, 0.0]))
    assert d == pytest.approx([one_degree * 90, one_degree * 180, one_degree * 90], rel=1e-12)


def test_bearing_cardinal_directions():
    lat, lon = 45.0, 7.0
    got = [geo.bearing_deg(lat, lon, lat + 0.01, lon), geo.bearing_deg(lat, lon, lat, lon + 0.01),
           geo.bearing_deg(lat, lon, lat - 0.01, lon), geo.bearing_deg(lat, lon, lat, lon - 0.01)]
    assert got[0] == pytest.approx(0.0, abs=1e-9) or got[0] == pytest.approx(360.0, abs=1e-9)
    assert got[1:] == pytest.approx([90.0, 180.0, 270.0], abs=0.01)


def test_great_circle_points_ends_and_spacing():
    pts = geo.great_circle_points((10.0, 20.0), (-5.0, 40.0), 5)
    assert pts[0] == (10.0, 20.0) and pts[-1] == (-5.0, 40.0)
    steps = [geo.haversine_m(*a, *b) for a, b in zip(pts, pts[1:])]
    assert max(steps) - min(steps) < 1e-3
    with pytest.raises(ValueError):
        geo.great_circle_points((10.0, 20.0), (-5.0, 40.0), 1)


def test_max_offset_is_zero_on_a_meridian():
    assert geo.max_offset_km((10.0, 5.0), (40.0, 5.0)) < 1e-6


def test_radii_equator_and_pole():
    m, n = geo.radii(0.0)
    assert n == pytest.approx(geo.WGS84_A, abs=1e-6)
    assert m == pytest.approx(geo.WGS84_A * (1 - geo.WGS84_E2), abs=1e-6)
    m, n = geo.radii(90.0)
    assert m == pytest.approx(n, abs=1e-6)


def test_ecef_round_trip():
    for p in [(46.5, 6.6, 400.0), (-45.0, -70.0, -30.0), (70.0, 179.0, 9000.0)]:
        back = geo.ecef_to_geodetic(*geo.geodetic_to_ecef(*p))
        assert back[0] == pytest.approx(p[0], abs=1e-9)
        assert back[1] == pytest.approx(p[1], abs=1e-9)
        assert back[2] == pytest.approx(p[2], abs=1e-3)


def test_enu_matrix_is_a_rotation():
    r = geo.enu_matrix(-12.0, 130.0)
    assert np.allclose(r @ r.T, np.eye(3), atol=1e-12)
    assert np.linalg.det(r) == pytest.approx(1.0, abs=1e-12)


def test_enu_round_trip_and_up():
    home = (40.4, -3.7, 650.0)
    assert geo.geodetic_to_enu(40.4, -3.7, 750.0, *home)[2] == pytest.approx(100.0, abs=1e-6)
    for enu in [(1200.0, -300.0, 15.0), (-20_000.0, 35_000.0, -60.0)]:
        lat, lon, h = geo.enu_to_geodetic(*enu, *home)
        assert geo.geodetic_to_enu(lat, lon, h, *home) == pytest.approx(enu, abs=1e-3)
